import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Installation / Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),s={name:"installation.md"};function n(r,e,l,h,p,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="installation-upgrading" tabindex="-1">Installation / Upgrading <a class="header-anchor" href="#installation-upgrading" aria-label="Permalink to &quot;Installation / Upgrading&quot;">​</a></h1><h3 id="option-1-composer" tabindex="-1">Option 1: Composer <a class="header-anchor" href="#option-1-composer" aria-label="Permalink to &quot;Option 1: Composer&quot;">​</a></h3><p>Composer is a simple, straight forward installation. Simply run the following command from your project root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flipboxfactory/saml-sp</span></span></code></pre></div><h3 id="option-2-plugin-store" tabindex="-1">Option 2: Plugin Store <a class="header-anchor" href="#option-2-plugin-store" aria-label="Permalink to &quot;Option 2: Plugin Store&quot;">​</a></h3><p>Within your Craft CMS project admin panel, navigate to the &#39;Plugin Store&#39; and search for <code>SAML SSO Service Provider</code>. Installation is a button click away.</p><p>Once the plugin is installed, head over to <a href="/configure/">configure</a> the plugin.</p><h2 id="upgrading-to-5-1-4" tabindex="-1">Upgrading to 5.1.4 <a class="header-anchor" href="#upgrading-to-5-1-4" aria-label="Permalink to &quot;Upgrading to 5.1.4&quot;">​</a></h2><p>5.1.4 is a security release (see the <a href="https://github.com/flipboxfactory/saml-sp/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>). It requires Craft CMS 5.10.8 or later, so update Craft first if needed.</p><p>saml-sp 5.1.4 uses <code>simplesamlphp/saml2</code> 4.19.x, which needs <code>webmozart/assert</code> 1.x, while recent Craft projects lock 2.x. If Composer reports a <code>webmozart/assert</code> conflict, allow it to adjust dependencies with <code>-W</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flipboxfactory/saml-sp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -W</span></span></code></pre></div><h2 id="upgrading-to-2-0" tabindex="-1">Upgrading to 2.0 <a class="header-anchor" href="#upgrading-to-2-0" aria-label="Permalink to &quot;Upgrading to 2.0&quot;">​</a></h2><p>There are a lot of breaking changes in 2.0. Upgrading is seamless if there is not any custom code that hooks into the SAML SP plugin.</p><h3 id="when-changes-are-needed" tabindex="-1">When Changes are Needed <a class="header-anchor" href="#when-changes-are-needed" aria-label="Permalink to &quot;When Changes are Needed&quot;">​</a></h3><p>You will need to refactor some of the code if you are doing any of the following:</p><ol><li>Hooking into the plugin with Craft/Yii2 Events. See a <a href="/configure/events.html#list">list of the events</a>.</li><li>Are using callables/anonymous functions with the <code>responseAttributeMap</code> config within <code>config/saml-sp.php</code>.</li><li>Have any references to <a href="https://github.com/lightSAML/lightSAML" target="_blank" rel="noreferrer">lightsaml/lightsaml</a> package. We have switch from using this package to using <a href="https://github.com/simplesamlphp/saml2" target="_blank" rel="noreferrer">simplesamlphp/saml2</a></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Search for <code>LightSaml</code> within your project to find items that need to be refactored.</p></div><h3 id="be-diligent-with-this-upgrade" tabindex="-1">Be Diligent with this Upgrade! <a class="header-anchor" href="#be-diligent-with-this-upgrade" aria-label="Permalink to &quot;Be Diligent with this Upgrade!&quot;">​</a></h3><ol><li>Backup the production database</li><li>Test the upgrade on a dev instance</li><li>Test Login/SSO and Logout/SLO (if logout is used)</li></ol><p><a href="https://github.com/flipboxfactory/saml-sp/issues" target="_blank" rel="noreferrer">Submit an Issue</a> or <a href="https://www.flipboxdigital.com/contact" target="_blank" rel="noreferrer">Contact us</a> if you are running into any problems.</p>',20)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
